  \begin{tikzpicture}[
    node distance=2cm,
    inner sep=0pt,
    outer sep=0pt]
    \node (a) at (0,0) {#1};
    \foreach \x/\y in {1/8, 2/7, 3/6, 4/5, 5/4, 6/3, 7/2, 8/1} {
